import React, { useState, useEffect } from 'react';
import { Copy, Check } from 'lucide-react';

interface TerminalOutputProps {
  command: string;
  isAnimated?: boolean;
}

const TerminalOutput: React.FC<TerminalOutputProps> = ({ command, isAnimated = false }) => {
  const [copied, setCopied] = useState(false);
  const [displayText, setDisplayText] = useState(isAnimated ? '' : command);

  useEffect(() => {
    if (!isAnimated) return;

    let i = 0;
    const interval = setInterval(() => {
      setDisplayText(command.substring(0, i));
      i++;
      if (i > command.length) clearInterval(interval);
    }, 20);

    return () => clearInterval(interval);
  }, [command, isAnimated]);

  const handleCopy = () => {
    navigator.clipboard.writeText(command);
    setCopied(true);
    setTimeout(() => setCopied(false), 2000);
  };

  return (
    <div className="group relative bg-[#050505] rounded-xl border border-zinc-800 overflow-hidden font-mono text-sm shadow-2xl">
      <div className="flex items-center justify-between px-4 py-2 bg-zinc-900/50 border-b border-zinc-800">
        <div className="flex gap-1.5">
          <div className="w-3 h-3 rounded-full bg-red-500/20 border border-red-500/50"></div>
          <div className="w-3 h-3 rounded-full bg-amber-500/20 border border-amber-500/50"></div>
          <div className="w-3 h-3 rounded-full bg-emerald-500/20 border border-emerald-500/50"></div>
        </div>
        <button 
          onClick={handleCopy}
          className="text-zinc-500 hover:text-emerald-400 transition-colors"
        >
          {copied ? <Check size={14} /> : <Copy size={14} />}
        </button>
      </div>
      <div className="p-4 text-emerald-500/90 leading-relaxed whitespace-pre-wrap break-all">
        <span className="text-zinc-600 mr-2">$</span>
        {displayText}
        <span className="inline-block w-2 h-4 bg-emerald-500 ml-1 animate-pulse"></span>
      </div>
    </div>
  );
};

export default TerminalOutput;

