import React, { useState, useRef, useEffect } from 'react';
import { Send, Bot, User, Trash2, HelpCircle } from 'lucide-react';
import { ChatMessage } from '../types';
import { getGeminiResponse } from '../services/geminiService';
import ReactMarkdown from 'react-markdown';

const AIShell: React.FC = () => {
  const [messages, setMessages] = useState<ChatMessage[]>([]);
  const [input, setInput] = useState('');
  const [isLoading, setIsLoading] = useState(false);
  const scrollRef = useRef<HTMLDivElement>(null);

  useEffect(() => {
    if (scrollRef.current) {
      scrollRef.current.scrollTop = scrollRef.current.scrollHeight;
    }
  }, [messages]);

  const handleSend = async () => {
    if (!input.trim() || isLoading) return;

    const userMsg: ChatMessage = { role: 'user', content: input, timestamp: new Date() };
    setMessages(prev => [...prev, userMsg]);
    setInput('');
    setIsLoading(true);

    const response = await getGeminiResponse(input);
    const aiMsg: ChatMessage = { role: 'model', content: response, timestamp: new Date() };
    setMessages(prev => [...prev, aiMsg]);
    setIsLoading(false);
  };

  const clearHistory = () => {
    if (confirm("Clear all conversation history?")) {
      setMessages([]);
    }
  };

  return (
    <div className="flex flex-col h-[calc(100vh-4rem)] max-w-4xl mx-auto p-4 md:p-8">
      <header className="flex items-center justify-between mb-8 bg-[#121212] border border-zinc-800 p-4 rounded-2xl">
        <div className="flex items-center gap-3">
          <div className="p-2 bg-emerald-500/10 text-emerald-400 rounded-lg">
            <Bot size={24} />
          </div>
          <div>
            <h2 className="text-lg font-bold text-white">AI Shell Assistant</h2>
            <p className="text-xs text-zinc-500">Gemini-3-Flash Optimization Active</p>
          </div>
        </div>
        <button 
          onClick={clearHistory}
          className="p-2 text-zinc-500 hover:text-red-400 hover:bg-red-400/10 rounded-lg transition-all"
        >
          <Trash2 size={20} />
        </button>
      </header>

      <div 
        ref={scrollRef}
        className="flex-1 overflow-y-auto space-y-6 pr-4 custom-scrollbar"
      >
        {messages.length === 0 && (
          <div className="h-full flex flex-col items-center justify-center text-center space-y-4 opacity-50">
            <HelpCircle size={48} className="text-zinc-600" />
            <div>
              <p className="text-lg font-medium text-zinc-400">How can I help you in Termux today?</p>
              <p className="text-sm text-zinc-600 max-w-sm">Try asking: "How do I install python and create a virtual env?" or "Explain what nmap -sP does."</p>
            </div>
          </div>
        )}

        {messages.map((msg, i) => (
          <div 
            key={i} 
            className={`flex gap-4 ${msg.role === 'user' ? 'flex-row-reverse' : 'flex-row'}`}
          >
            <div className={`flex-shrink-0 w-10 h-10 rounded-xl flex items-center justify-center border shadow-lg ${
              msg.role === 'user' 
                ? 'bg-zinc-800 border-zinc-700 text-zinc-300' 
                : 'bg-emerald-500/10 border-emerald-500/20 text-emerald-400'
            }`}>
              {msg.role === 'user' ? <User size={20} /> : <Bot size={20} />}
            </div>
            <div className={`max-w-[85%] px-5 py-4 rounded-2xl shadow-xl prose prose-invert prose-emerald ${
              msg.role === 'user' 
                ? 'bg-emerald-600 text-white rounded-tr-none' 
                : 'bg-[#121212] border border-zinc-800 text-zinc-200 rounded-tl-none'
            }`}>
              <ReactMarkdown 
                components={{
                  code: ({ node, ...props }) => (
                    <code className="bg-zinc-950 px-1.5 py-0.5 rounded font-mono text-emerald-400" {...props} />
                  ),
                  pre: ({ node, ...props }) => (
                    <pre className="bg-zinc-950 p-4 rounded-xl border border-zinc-800 overflow-x-auto my-4 font-mono text-sm" {...props} />
                  )
                }}
              >
                {msg.content}
              </ReactMarkdown>
              <div className="mt-2 text-[10px] opacity-40 font-mono">
                {msg.timestamp.toLocaleTimeString([], { hour: '2-digit', minute: '2-digit' })}
              </div>
            </div>
          </div>
        ))}
        {isLoading && (
          <div className="flex gap-4">
            <div className="w-10 h-10 rounded-xl bg-emerald-500/10 border border-emerald-500/20 flex items-center justify-center text-emerald-400">
              <Bot size={20} className="animate-spin" />
            </div>
            <div className="bg-[#121212] border border-zinc-800 px-6 py-4 rounded-2xl rounded-tl-none">
              <div className="flex gap-1.5">
                <div className="w-1.5 h-1.5 bg-emerald-500 rounded-full animate-bounce"></div>
                <div className="w-1.5 h-1.5 bg-emerald-500 rounded-full animate-bounce [animation-delay:0.2s]"></div>
                <div className="w-1.5 h-1.5 bg-emerald-500 rounded-full animate-bounce [animation-delay:0.4s]"></div>
              </div>
            </div>
          </div>
        )}
      </div>

      <div className="mt-8 relative group">
        <input 
          type="text"
          value={input}
          onChange={(e) => setInput(e.target.value)}
          onKeyPress={(e) => e.key === 'Enter' && handleSend()}
          placeholder="Type your command query..."
          className="w-full bg-[#121212] border border-zinc-800 text-white pl-6 pr-16 py-4 rounded-2xl focus:outline-none focus:ring-2 focus:ring-emerald-500/40 focus:border-emerald-500 transition-all shadow-2xl"
        />
        <button 
          onClick={handleSend}
          disabled={!input.trim() || isLoading}
          className="absolute right-3 top-2.5 p-2.5 bg-emerald-500 text-white rounded-xl hover:bg-emerald-400 transition-all disabled:opacity-50 disabled:cursor-not-allowed shadow-lg"
        >
          <Send size={20} />
        </button>
      </div>
    </div>
  );
};

export default AIShell;

