import { GoogleGenAI, GenerateContentResponse } from "@google/genai";

const SYSTEM_INSTRUCTION = `
You are the "Termux Toolkit Assistant", a specialized AI for users running Linux inside Termux on Android.
Your expertise covers:
1. Command generation: Help users write complex shell commands using pkg, apt, and Termux-specific binaries.
2. Scripting: Help write Bash, Python, or Ruby scripts optimized for the mobile environment.
3. Troubleshooting: Explain error codes specific to Android/Termux environments.
4. Security: Provide safe, ethical guidance on networking and system administration.

Always use a professional, slightly technical tone. 
Wrap commands in markdown code blocks: \`pkg install nodejs\`.
Warn users before suggesting destructive commands like 'rm -rf /'.
Mention Termux-specific tools like 'termux-api', 'termux-storage-get', etc., when relevant.
`;

const TERMINAL_SIMULATION_INSTRUCTION = `
You are a high-fidelity Linux Terminal Emulator running inside Termux on an Android device.
The user will input a command. You must respond with the EXACT STDOUT/STDERR output that a Termux environment would produce.

Rules:
1. Provide ONLY the terminal output. 
2. NO conversational text, NO markdown formatting (except for code if necessary, but ideally raw text).
3. NO explanations.
4. If a command is missing, show a bash-style error: "bash: [command]: command not found".
5. If the user asks for a file list (ls), simulate a realistic directory structure (e.g., includes 'storage', 'scripts', 'downloads').
6. Simulate common Termux behavior (e.g., 'pkg' output with progress bars, 'apt' headers).
7. Keep it brief and technical.
`;

const REMOTE_SSH_INSTRUCTION = `
You are simulating a REMOTE SSH SERVER. 
The user is connected to you via SSH from their Termux environment.
The hostname is [HOSTNAME]. The user is [USER].

Rules:
1. Provide ONLY the terminal output of the command.
2. The environment should feel like a standard cloud Linux server (Ubuntu/Debian).
3. If the user runs 'exit', return: "logout\nConnection to [HOSTNAME] closed."
4. Maintain a consistent simulated file system for this session.
5. Do NOT use Termux-specific commands like 'pkg' unless the remote server is another Termux instance (assume standard apt/yum).
`;

const SCRIPT_GEN_INSTRUCTION = `
You are a senior DevOps engineer specialized in Termux.
Your goal is to generate robust, clean, and well-commented bash scripts for tool installation and setup.

Rules:
1. Output ONLY the bash code.
2. No conversational filler like "Here is your script".
3. Use 'pkg' for package management.
4. Include an 'official' look: add a header with tool name and version info.
5. Include basic error handling (e.g., exit if a command fails).
6. Ensure the script is safe for mobile environments.
`;

export const getGeminiResponse = async (prompt: string): Promise<string> => {
  try {
    const ai = new GoogleGenAI({ apiKey: process.env.API_KEY || '' });
    const response: GenerateContentResponse = await ai.models.generateContent({
      model: 'gemini-3-flash-preview',
      contents: prompt,
      config: {
        systemInstruction: SYSTEM_INSTRUCTION,
        temperature: 0.7,
        topP: 0.95,
      },
    });

    return response.text || "I'm sorry, I couldn't generate a response.";
  } catch (error) {
    console.error("Gemini API Error:", error);
    return "Error: Unable to connect to the AI assistant. Please check your network or API configuration.";
  }
};

export const simulateCommandExecution = async (command: string): Promise<string> => {
  try {
    const ai = new GoogleGenAI({ apiKey: process.env.API_KEY || '' });
    const response: GenerateContentResponse = await ai.models.generateContent({
      model: 'gemini-3-flash-preview',
      contents: `Execute this command and show output: ${command}`,
      config: {
        systemInstruction: TERMINAL_SIMULATION_INSTRUCTION,
        temperature: 0.2,
        topP: 0.9,
      },
    });

    return response.text || "";
  } catch (error) {
    console.error("Command Simulation Error:", error);
    return `bash: ${command.split(' ')[0]}: execution failed (API error)`;
  }
};

export const simulateSshRemoteExecution = async (command: string, user: string, host: string): Promise<string> => {
  try {
    const ai = new GoogleGenAI({ apiKey: process.env.API_KEY || '' });
    const response: GenerateContentResponse = await ai.models.generateContent({
      model: 'gemini-3-flash-preview',
      contents: `Command on ${user}@${host}: ${command}`,
      config: {
        systemInstruction: REMOTE_SSH_INSTRUCTION.replace('[HOSTNAME]', host).replace('[USER]', user),
        temperature: 0.3,
        topP: 0.9,
      },
    });

    return response.text || "";
  } catch (error) {
    console.error("SSH Simulation Error:", error);
    return `ssh: connect to host ${host} port 22: Connection timed out`;
  }
};

export const generateToolScript = async (toolName: string, description: string): Promise<string> => {
  try {
    const ai = new GoogleGenAI({ apiKey: process.env.API_KEY || '' });
    const response: GenerateContentResponse = await ai.models.generateContent({
      model: 'gemini-3-flash-preview',
      contents: `Generate a bash setup script for ${toolName}. Description: ${description}`,
      config: {
        systemInstruction: SCRIPT_GEN_INSTRUCTION,
        temperature: 0.4,
        topP: 0.9,
      },
    });

    return response.text?.trim() || "# Error generating script";
  } catch (error) {
    console.error("Script Generation Error:", error);
    return "# Error: Failed to contact Gemini API for script generation.";
  }
};

import React, { useState, useRef, useEffect } from 'react';
import { Send, Bot, User, Trash2, HelpCircle, Terminal as TerminalIcon, MessageSquare, ChevronRight, Globe } from 'lucide-react';
import { ChatMessage, MessageType } from '../types';
import { getGeminiResponse, simulateCommandExecution, simulateSshRemoteExecution } from '../services/geminiService';
import ReactMarkdown from 'react-markdown';
import TerminalOutput from './TerminalOutput';

const AIShell: React.FC = () => {
  const [messages, setMessages] = useState<ChatMessage[]>([]);
  const [input, setInput] = useState('');
  const [isLoading, setIsLoading] = useState(false);
  const [mode, setMode] = useState<MessageType>('chat');
  const [sshSession, setSshSession] = useState<{ user: string; host: string } | null>(null);
  const scrollRef = useRef<HTMLDivElement>(null);

  useEffect(() => {
    if (scrollRef.current) {
      scrollRef.current.scrollTop = scrollRef.current.scrollHeight;
    }
  }, [messages, isLoading]);

  const handleSend = async () => {
    if (!input.trim() || isLoading) return;

    const currentInput = input.trim();
    const currentMode = mode;

    // Create the user message
    const userMsg: ChatMessage = { 
      role: 'user', 
      type: currentMode,
      content: currentInput, 
      timestamp: new Date() 
    };

    setMessages(prev => [...prev, userMsg]);
    setInput('');
    setIsLoading(true);

    try {
      if (currentMode === 'command') {
        // Handle SSH logic
        if (!sshSession && currentInput.startsWith('ssh ')) {
          const parts = currentInput.split(' ');
          const target = parts[1]; // expecting user@host
          if (target && target.includes('@')) {
            const [user, host] = target.split('@');
            // Simulate connection delay
            await new Promise(resolve => setTimeout(resolve, 1500));
            const output = `The authenticity of host '${host}' can't be established.\nECDSA key fingerprint is SHA256:simulated_hash_value.\nAre you sure you want to continue connecting (yes/no)? yes\nWarning: Permanently added '${host}' (ECDSA) to the list of known hosts.\n${user}@${host}'s password: \nLast login: ${new Date().toUTCString()} from termux-session\nWelcome to simulated ${host}!`;

            const aiMsg: ChatMessage = { 
              role: 'model', 
              type: 'command',
              content: currentInput,
              output: output,
              timestamp: new Date() 
            };
            setMessages(prev => [...prev, aiMsg]);
            setSshSession({ user, host });
          } else {
            const output = `ssh: Could not resolve hostname ${target}: Name or service not known`;
            setMessages(prev => [...prev, { role: 'model', type: 'command', content: currentInput, output, timestamp: new Date() }]);
          }
        } 
        else if (sshSession) {
          if (currentInput === 'exit' || currentInput === 'logout') {
            const output = `logout\nConnection to ${sshSession.host} closed.`;
            setMessages(prev => [...prev, { role: 'model', type: 'command', content: currentInput, output, timestamp: new Date() }]);
            setSshSession(null);
          } else {
            const output = await simulateSshRemoteExecution(currentInput, sshSession.user, sshSession.host);
            setMessages(prev => [...prev, { role: 'model', type: 'command', content: currentInput, output, timestamp: new Date() }]);
          }
        }
        else {
          const output = await simulateCommandExecution(currentInput);
          setMessages(prev => [...prev, { role: 'model', type: 'command', content: currentInput, output, timestamp: new Date() }]);
        }
      } else {
        const response = await getGeminiResponse(currentInput);
        setMessages(prev => [...prev, { role: 'model', type: 'chat', content: response, timestamp: new Date() }]);
      }
    } catch (err) {
      console.error(err);
    } finally {
      setIsLoading(false);
    }
  };

  const clearHistory = () => {
    if (confirm("Clear all conversation history?")) {
      setMessages([]);
      setSshSession(null);
    }
  };

  const toggleMode = () => {
    setMode(prev => prev === 'chat' ? 'command' : 'chat');
  };

  return (
    <div className="flex flex-col h-[calc(100vh-4rem)] max-w-5xl mx-auto p-4 md:p-8">
      <header className="flex items-center justify-between mb-8 bg-[#121212] border border-zinc-800 p-4 rounded-2xl shadow-xl">
        <div className="flex items-center gap-3">
          <div className={`p-2 rounded-lg transition-colors ${
            sshSession 
              ? 'bg-blue-500/10 text-blue-400' 
              : (mode === 'chat' ? 'bg-emerald-500/10 text-emerald-400' : 'bg-cyan-500/10 text-cyan-400')
          }`}>
            {sshSession ? <Globe size={24} /> : (mode === 'chat' ? <Bot size={24} /> : <TerminalIcon size={24} />)}
          </div>
          <div>
            <h2 className="text-lg font-bold text-white">
              {sshSession ? `SSH: ${sshSession.user}@${sshSession.host}` : (mode === 'chat' ? 'AI Assistant' : 'Terminal Emulator')}
            </h2>
            <p className="text-xs text-zinc-500">
              {sshSession ? 'Connected to Remote Server' : (mode === 'chat' ? 'Ask anything about Termux' : 'Simulate bash command execution')}
            </p>
          </div>
        </div>

        <div className="flex items-center gap-2">
          {!sshSession && (
            <button 
              onClick={toggleMode}
              className={`flex items-center gap-2 px-4 py-2 rounded-xl text-sm font-medium transition-all ${
                mode === 'chat' 
                ? 'bg-cyan-500/10 text-cyan-400 border border-cyan-500/20 hover:bg-cyan-500/20' 
                : 'bg-emerald-500/10 text-emerald-400 border border-emerald-500/20 hover:bg-emerald-500/20'
              }`}
            >
              {mode === 'chat' ? <TerminalIcon size={16} /> : <MessageSquare size={16} />}
              Switch to {mode === 'chat' ? 'Terminal' : 'Chat'}
            </button>
          )}
          {sshSession && (
            <div className="px-4 py-2 bg-blue-500/10 text-blue-400 border border-blue-500/20 rounded-xl text-xs font-bold uppercase tracking-wider animate-pulse">
              Live Connection
            </div>
          )}
          <button 
            onClick={clearHistory}
            className="p-2.5 text-zinc-500 hover:text-red-400 hover:bg-red-400/10 rounded-xl transition-all"
            title="Clear History"
          >
            <Trash2 size={20} />
          </button>
        </div>
      </header>

      <div 
        ref={scrollRef}
        className="flex-1 overflow-y-auto space-y-6 pr-4 custom-scrollbar"
      >
        {messages.length === 0 && (
          <div className="h-full flex flex-col items-center justify-center text-center space-y-4 opacity-50">
            <HelpCircle size={48} className="text-zinc-600" />
            <div>
              <p className="text-lg font-medium text-zinc-400">
                {mode === 'chat' ? 'Ask me anything about Termux' : 'Enter a command to simulate'}
              </p>
              <p className="text-sm text-zinc-600 max-w-sm">
                {mode === 'chat' 
                  ? 'Try: "How do I setup an SSH server?" or "What is pkg?"' 
                  : 'Try: "ssh root@cloud-vm", "ls -la", or "pkg update"'}
              </p>
            </div>
          </div>
        )}

        {messages.map((msg, i) => (
          <div 
            key={i} 
            className={`flex gap-4 ${msg.role === 'user' ? 'flex-row-reverse' : 'flex-row'}`}
          >
            <div className={`flex-shrink-0 w-10 h-10 rounded-xl flex items-center justify-center border shadow-lg ${
              msg.role === 'user' 
                ? 'bg-zinc-800 border-zinc-700 text-zinc-300' 
                : (msg.type === 'command' ? 'bg-cyan-500/10 border-cyan-500/20 text-cyan-400' : 'bg-emerald-500/10 border-emerald-500/20 text-emerald-400')
            }`}>
              {msg.role === 'user' ? <User size={20} /> : (msg.type === 'command' ? <TerminalIcon size={20} /> : <Bot size={20} />)}
            </div>

            <div className={`max-w-[90%] space-y-2 ${msg.role === 'user' ? 'text-right' : ''}`}>
              <div className={`inline-block px-5 py-3.5 rounded-2xl shadow-xl transition-all ${
                msg.role === 'user' 
                  ? (msg.type === 'command' ? 'bg-cyan-600 text-white rounded-tr-none font-mono text-sm' : 'bg-emerald-600 text-white rounded-tr-none') 
                  : (msg.type === 'command' ? 'w-full' : 'bg-[#121212] border border-zinc-800 text-zinc-200 rounded-tl-none')
              }`}>
                {msg.type === 'command' && msg.role === 'user' && (
                  <div className="flex items-center gap-2">
                    <span className="opacity-60">
                      {sshSession ? `${sshSession.user}@${sshSession.host}:~$` : '$'}
                    </span>
                    {msg.content}
                  </div>
                )}

                {msg.type === 'chat' && (
                  <div className="prose prose-invert prose-emerald prose-sm max-w-none">
                    <ReactMarkdown 
                      components={{
                        code: ({ node, ...props }) => (
                          <code className="bg-zinc-950 px-1.5 py-0.5 rounded font-mono text-emerald-400" {...props} />
                        ),
                        pre: ({ node, ...props }) => (
                          <pre className="bg-zinc-950 p-4 rounded-xl border border-zinc-800 overflow-x-auto my-4 font-mono text-xs md:text-sm" {...props} />
                        )
                      }}
                    >
                      {msg.content}
                    </ReactMarkdown>
                  </div>
                )}

                {msg.type === 'command' && msg.role === 'model' && msg.output && (
                  <div className="w-full">
                    <TerminalOutput 
                      command={msg.output} 
                      isAnimated={true} 
                      color={sshSession ? 'blue' : 'emerald'}
                    />
                  </div>
                )}
              </div>
              <div className="text-[10px] text-zinc-600 font-mono">
                {msg.timestamp.toLocaleTimeString([], { hour: '2-digit', minute: '2-digit' })}
              </div>
            </div>
          </div>
        ))}

        {isLoading && (
          <div className="flex gap-4">
            <div className={`w-10 h-10 rounded-xl flex items-center justify-center border animate-pulse ${mode === 'chat' ? 'bg-emerald-500/10 border-emerald-500/20 text-emerald-400' : 'bg-cyan-500/10 border-cyan-500/20 text-cyan-400'}`}>
              {sshSession ? <Globe size={20} className="animate-spin" /> : (mode === 'chat' ? <Bot size={20} className="animate-spin" /> : <TerminalIcon size={20} className="animate-pulse" />)}
            </div>
            <div className="bg-[#121212] border border-zinc-800 px-6 py-4 rounded-2xl rounded-tl-none shadow-lg">
              <div className="flex gap-1.5">
                <div className={`w-1.5 h-1.5 rounded-full animate-bounce ${sshSession ? 'bg-blue-500' : (mode === 'chat' ? 'bg-emerald-500' : 'bg-cyan-500')}`}></div>
                <div className={`w-1.5 h-1.5 rounded-full animate-bounce [animation-delay:0.2s] ${sshSession ? 'bg-blue-500' : (mode === 'chat' ? 'bg-emerald-500' : 'bg-cyan-500')}`}></div>
                <div className={`w-1.5 h-1.5 rounded-full animate-bounce [animation-delay:0.4s] ${sshSession ? 'bg-blue-500' : (mode === 'chat' ? 'bg-emerald-500' : 'bg-cyan-500')}`}></div>
              </div>
            </div>
          </div>
        )}
      </div>

      <div className="mt-8 flex flex-col gap-3">
        {mode === 'command' && !sshSession && (
          <div className="flex flex-wrap gap-2 mb-1">
            {['ssh root@192.168.1.10', 'ls -la', 'pkg update', 'whoami', 'pwd'].map(cmd => (
              <button 
                key={cmd}
                onClick={() => setInput(cmd)}
                className="px-3 py-1 bg-zinc-900 border border-zinc-800 text-zinc-500 text-[10px] font-mono rounded-lg hover:border-cyan-500/50 hover:text-cyan-400 transition-all"
              >
                {cmd}
              </button>
            ))}
          </div>
        )}
        {sshSession && (
          <div className="flex flex-wrap gap-2 mb-1">
            {['uname -a', 'htop', 'ls /var/log', 'cat /etc/os-release', 'exit'].map(cmd => (
              <button 
                key={cmd}
                onClick={() => setInput(cmd)}
                className="px-3 py-1 bg-zinc-900 border border-zinc-800 text-zinc-500 text-[10px] font-mono rounded-lg hover:border-blue-500/50 hover:text-blue-400 transition-all"
              >
                {cmd}
              </button>
            ))}
          </div>
        )}
        <div className="relative group">
          <div className={`absolute left-5 top-1/2 -translate-y-1/2 font-mono text-lg transition-colors ${
            sshSession ? 'text-blue-500' : (mode === 'command' ? 'text-cyan-500' : 'text-emerald-500')
          }`}>
            {sshSession ? <Globe size={20} /> : (mode === 'command' ? <ChevronRight size={20} /> : <MessageSquare size={20} />)}
          </div>
          <input 
            type="text"
            value={input}
            onChange={(e) => setInput(e.target.value)}
            onKeyPress={(e) => e.key === 'Enter' && handleSend()}
            placeholder={sshSession ? `Execute command on ${sshSession.host}...` : (mode === 'chat' ? "Ask the AI assistant..." : "Enter shell command...")}
            className={`w-full bg-[#121212] border border-zinc-800 text-white pl-12 pr-16 py-5 rounded-2xl focus:outline-none focus:ring-4 transition-all shadow-2xl font-mono text-sm md:text-base ${
              sshSession 
                ? 'focus:ring-blue-500/10 focus:border-blue-500 border-blue-500/30'
                : (mode === 'chat' ? 'focus:ring-emerald-500/10 focus:border-emerald-500' : 'focus:ring-cyan-500/10 focus:border-cyan-500')
            }`}
          />
          <button 
            onClick={handleSend}
            disabled={!input.trim() || isLoading}
            className={`absolute right-3 top-1/2 -translate-y-1/2 p-3 text-white rounded-xl transition-all disabled:opacity-50 disabled:cursor-not-allowed shadow-lg ${
              sshSession ? 'bg-blue-600 hover:bg-blue-500' : (mode === 'chat' ? 'bg-emerald-600 hover:bg-emerald-500' : 'bg-cyan-600 hover:bg-cyan-500')
            }`}
          >
            <Send size={20} />
          </button>
        </div>
        <div className="flex items-center justify-between px-2">
          <p className="text-[10px] text-zinc-600 font-mono uppercase tracking-widest">
            {sshSession ? `Remote Session Active: encrypted simulation` : (mode === 'command' ? 'Simulation Mode: Results are predictive' : 'Conversation Mode: System knowledge up to 2024')}
          </p>
          <div className="flex items-center gap-1">
             <div className={`w-1.5 h-1.5 rounded-full ${sshSession ? 'bg-blue-500' : (mode === 'chat' ? 'bg-emerald-500' : 'bg-cyan-500')} animate-pulse`}></div>
             <span className="text-[10px] text-zinc-600 font-mono uppercase">Ready</span>
          </div>
        </div>
      </div>
    </div>
  );
};

export default AIShell;

import React, { useState, useEffect, useRef } from 'react';
import { Copy, Check } from 'lucide-react';

interface TerminalOutputProps {
  command: string;
  isAnimated?: boolean;
  color?: 'emerald' | 'blue' | 'cyan' | 'amber';
}

const TerminalOutput: React.FC<TerminalOutputProps> = ({ 
  command, 
  isAnimated = false,
  color = 'emerald'
}) => {
  const [copied, setCopied] = useState(false);
  const [displayText, setDisplayText] = useState(isAnimated ? '' : command);
  const containerRef = useRef<HTMLDivElement>(null);

  const colorMap = {
    emerald: 'text-emerald-500/90',
    blue: 'text-blue-400/90',
    cyan: 'text-cyan-400/90',
    amber: 'text-amber-400/90'
  };

  const borderMap = {
    emerald: 'border-emerald-500/30',
    blue: 'border-blue-500/30',
    cyan: 'border-cyan-500/30',
    amber: 'border-amber-500/30'
  };

  const bgMap = {
    emerald: 'bg-emerald-500',
    blue: 'bg-blue-500',
    cyan: 'bg-cyan-500',
    amber: 'bg-amber-500'
  };

  useEffect(() => {
    if (!isAnimated) {
      setDisplayText(command);
      return;
    }

    let i = 0;
    const interval = setInterval(() => {
      setDisplayText(command.substring(0, i));
      i += 3; // Type faster for long outputs
      if (i > command.length) {
        setDisplayText(command);
        clearInterval(interval);
      }
    }, 10);

    return () => clearInterval(interval);
  }, [command, isAnimated]);

  useEffect(() => {
    if (containerRef.current) {
      containerRef.current.scrollTop = containerRef.current.scrollHeight;
    }
  }, [displayText]);

  const handleCopy = () => {
    navigator.clipboard.writeText(command);
    setCopied(true);
    setTimeout(() => setCopied(false), 2000);
  };

  return (
    <div className={`group relative bg-[#050505] rounded-xl border border-zinc-800 overflow-hidden font-mono text-sm shadow-2xl w-full ${isAnimated ? 'transition-all duration-500' : ''}`}>
      <div className="flex items-center justify-between px-4 py-2 bg-zinc-900/50 border-b border-zinc-800">
        <div className="flex gap-1.5">
          <div className="w-3 h-3 rounded-full bg-red-500/20 border border-red-500/50"></div>
          <div className="w-3 h-3 rounded-full bg-amber-500/20 border border-amber-500/50"></div>
          <div className="w-3 h-3 rounded-full bg-emerald-500/20 border border-emerald-500/50"></div>
        </div>
        <button 
          onClick={handleCopy}
          className="text-zinc-500 hover:text-white transition-colors p-1"
          title="Copy Output"
        >
          {copied ? <Check size={14} className="text-emerald-400" /> : <Copy size={14} />}
        </button>
      </div>
      <div 
        ref={containerRef}
        className={`p-4 ${colorMap[color]} leading-relaxed whitespace-pre overflow-x-auto max-h-[400px] custom-scrollbar scroll-smooth`}
      >
        {displayText}
        {isAnimated && displayText.length < command.length && (
          <span className={`inline-block w-2 h-4 ${bgMap[color]} ml-1 animate-pulse align-middle`}></span>
        )}
      </div>
    </div>
  );
};

